// ═══ CLASSIC SWITCH — fall-through bugs ═══
// (Avoid) Forgot break → falls through!
String oldWay;
switch (status) {
    case "SETTLED":
        oldWay = "Completed";
        break;  // forget this → falls to PENDING!
    case "PENDING":
        oldWay = "In Progress";
        break;
    default:
        oldWay = "Unknown";
}

// ═══ SWITCH EXPRESSION — no fall-through, returns value ═══
String newWay = switch (status) {
    case "SETTLED" -> "Completed";          // arrow = no fall-through
    case "PENDING" -> "In Progress";
    case "FAILED"  -> "Error";
    default        -> "Unknown";
};  // note the semicolon — it's an expression assigned to a variable!

// ═══ MULTIPLE LABELS ═══
String category = switch (txnType) {
    case "NEFT", "RTGS", "IMPS" -> "Transfer";
    case "UPI"                   -> "Digital Payment";
    case "ATM", "POS"            -> "Cash/Card";
    default                      -> "Other";
};

// ═══ YIELD — return from block ═══
int riskScore = switch (country) {
    case "INDIA" -> 1;
    case "USA", "UK" -> 2;
    case "NIGERIA" -> {
        log.warn("High-risk country detected!");
        yield 9;  // yield returns value from block
    }
    default -> 5;
};

// ═══ EXHAUSTIVENESS — enum must cover all cases ═══
enum Status { SETTLED, PENDING, FAILED }

String describe(Status s) {
    return switch (s) {
        case SETTLED -> "Done";
        case PENDING -> "Waiting";
        case FAILED  -> "Error";
        // No default needed — compiler knows all enum values covered!
        // Add a new enum value → COMPILE ERROR until handled here!
    };
}

// ═══ PATTERN MATCHING SWITCH (Java 21) ═══
String process(Object obj) {
    return switch (obj) {
        case Integer i when i > 0 -> "Positive: " + i;
        case Integer i            -> "Non-positive: " + i;
        case String s             -> "String: " + s;
        case null                 -> "null";
        default                   -> "Other: " + obj;
    };
}
