package com.bank.switchexp;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class SwitchExpressionTest {

    @Test void arrowSyntaxReturnsValue() {
        String result = switch ("SETTLED") {
            case "SETTLED" -> "Done";
            case "PENDING" -> "Waiting";
            default -> "Unknown";
        };
        assertThat(result).isEqualTo("Done");
    }

    @Test void multipleLabels() {
        String cat = switch ("RTGS") {
            case "NEFT", "RTGS", "IMPS" -> "Transfer";
            default -> "Other";
        };
        assertThat(cat).isEqualTo("Transfer");
    }

    @Test void yieldFromBlock() {
        int score = switch ("NIGERIA") {
            case "INDIA" -> 1;
            case "NIGERIA" -> { log("high risk"); yield 9; }
            default -> 5;
        };
        assertThat(score).isEqualTo(9);
    }

    @Test void patternMatchingSwitch() {
        String result = switch ((Object) 42) {
            case Integer i when i > 0 -> "Positive";
            case Integer i -> "Non-positive";
            case String s -> "String";
            default -> "Other";
        };
        assertThat(result).isEqualTo("Positive");
    }

    @Test void nullHandling() {
        String result = switch ((String) null) {
            case null -> "null value";
            case "A" -> "A";
            default -> "other";
        };
        assertThat(result).isEqualTo("null value");
    }

    private void log(String msg) { /* logging */ }
}
