package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.assertThat;

class SwitchExpressionTest {

    enum AccountType { SAVINGS, CURRENT, FD }

    BigDecimal rate(AccountType type) {
        return switch (type) {                      // expression, arrow, exhaustive
            case SAVINGS -> new BigDecimal("3.5");
            case CURRENT -> BigDecimal.ZERO;
            case FD      -> new BigDecimal("7.1");
        };
    }

    @Test
    void arrowSwitchReturnsValue() {
        assertThat(rate(AccountType.SAVINGS)).isEqualByComparingTo("3.5");
        assertThat(rate(AccountType.FD)).isEqualByComparingTo("7.1");
        assertThat(rate(AccountType.CURRENT)).isEqualByComparingTo("0");
    }
}
